const syncNameOverlayHostToSvg = useCallback(
  (host: HTMLElement, textEl: SVGTextElement, root: HTMLElement) => {
    const svg = textEl.ownerSVGElement;
    const ctm = textEl.getScreenCTM();
    if (!svg || !ctm) return;

    const rootRect = root.getBoundingClientRect();
    const pt = svg.createSVGPoint();
    pt.x = Number.parseFloat(textEl.getAttribute("x") || "0");
    pt.y = Number.parseFloat(textEl.getAttribute("y") || "0");
    const baseline = pt.matrixTransform(ctm);

    const cs = getComputedStyle(host);
    const fontSize = Number.parseFloat(cs.fontSize) || 16;
    let ascent = fontSize * 0.8;
    const canvas = document.createElement("canvas");
    const ctx = canvas.getContext("2d");
    if (ctx) {
      ctx.font = `${cs.fontWeight} ${cs.fontSize} ${cs.fontFamily}`.trim();
      const metrics = ctx.measureText(host.textContent || "M");
      if (metrics.actualBoundingBoxAscent > 0) {
        ascent = metrics.actualBoundingBoxAscent;
      }
    }

    host.style.left = `${baseline.x - rootRect.left}px`;
    host.style.top = `${baseline.y - rootRect.top - ascent}px`;

    /* Final pixel nudge — match SVG glyph box left after font metrics settle. */
    const textRect = textEl.getBoundingClientRect();
    const hostRect = host.getBoundingClientRect();
    if (textRect.width >= 1) {
      host.style.left = `${Number.parseFloat(host.style.left) + (textRect.left - hostRect.left)}px`;
    }
  },
  [],
);

old_string:
const syncNameOverlayHostToSvg = useCallback(
  (host: HTMLElement, textEl: SVGTextElement, root: HTMLElement) => {
    const rootRect = root.getBoundingClientRect();
    const textRect = textEl.getBoundingClientRect();
    if (textRect.width < 1 || textRect.height < 1) return;

    /* Pin host ink box to SVG text box (bottom) — locked visual position, no handoff jump. */
    const hostRect = host.getBoundingClientRect();
    const left =
      Number.parseFloat(host.style.left || "0") + (textRect.left - hostRect.left);
    const top =
      Number.parseFloat(host.style.top || String(textRect.top - rootRect.top)) +
      (textRect.bottom - hostRect.bottom);
    host.style.left = `${left}px`;
    host.style.top = `${top}px`;
  },
  [],
);
